BEGIN;
CREATE TEMP TABLE channel_principal_grants (LIKE public.channel_principal_grants INCLUDING ALL);
INSERT INTO channel_principal_grants(company_id,channel_id,principal_id,capability,provenance) SELECT '00000000-0000-0000-0000-000000000001'::uuid, md5('channel-'||desk)::uuid,md5('principal-'||person)::uuid,capability,'department_membership' FROM generate_series(1,200) AS desk CROSS JOIN generate_series(1,1000) AS person CROSS JOIN unnest(ARRAY['participate','view']) AS capability;
ANALYZE channel_principal_grants;
SELECT count(*) AS rows,pg_relation_size('channel_principal_grants') AS table_bytes,pg_indexes_size('channel_principal_grants') AS index_bytes FROM channel_principal_grants;
PREPARE original(uuid,uuid[],uuid[],uuid[],text[],text) AS 
    WITH desired AS (
        SELECT audience.channel_id, audience.principal_id, capability.value AS capability
          FROM unnest($3::uuid[], $4::uuid[]) AS audience(channel_id, principal_id)
          CROSS JOIN unnest($5::text[]) AS capability(value)
    )
    INSERT INTO channel_principal_grants
        (company_id, channel_id, principal_id, capability, provenance)
    SELECT $1, desired.channel_id, desired.principal_id, desired.capability, $6
      FROM desired WHERE desired.channel_id=ANY($2)
       AND NOT EXISTS (SELECT 1 FROM channel_principal_grants AS permission
            WHERE permission.company_id=$1 AND permission.channel_id=desired.channel_id
              AND permission.principal_id=desired.principal_id
              AND permission.capability=desired.capability AND permission.provenance=$6)
    ON CONFLICT (company_id, channel_id, principal_id, capability, provenance) DO NOTHING
;
PREPARE pruned(uuid,uuid[],uuid[],uuid[],text[],text) AS 
    WITH desired AS (
        SELECT audience.channel_id, audience.principal_id, capability.value AS capability
          FROM unnest($3::uuid[], $4::uuid[]) AS audience(channel_id, principal_id)
          CROSS JOIN unnest($5::text[]) AS capability(value)
    )
    INSERT INTO channel_principal_grants
        (company_id, channel_id, principal_id, capability, provenance)
    SELECT $1, desired.channel_id, desired.principal_id, desired.capability, $6
      FROM desired WHERE desired.channel_id=ANY($2)
       AND NOT EXISTS (SELECT 1 FROM channel_principal_grants AS permission
            WHERE permission.company_id=$1 AND permission.channel_id=ANY($2) AND permission.channel_id=desired.channel_id
              AND permission.principal_id=desired.principal_id
              AND permission.capability=desired.capability AND permission.provenance=$6)
    ON CONFLICT (company_id, channel_id, principal_id, capability, provenance) DO NOTHING
;
SET LOCAL plan_cache_mode=force_custom_plan;
SELECT 'force_custom_plan/original' AS experiment;
